    pr = subprocess.Popen(["node", "--max-old-space-size=3000",
                           "tdrv.js", lst],
                          stdout=subprocess.PIPE, text=True, cwd=drv)
    n = 0; t0 = time.time()
    for line in pr.stdout:
        line = line.strip()
        if "|" not in line: continue
        pid, v = line.split("|", 1)
        if pid == "__TOTAL_MS__": print("inner " + line); continue
        if pid == "__NOTE__": print("inner " + line); sys.stdout.flush(); continue
        verdicts[pid] = v; emit(pid, v, "")
        n += 1
        if n % 500 == 0:
            el = time.time()-t0
            print("[progress] typescript [%d/%d] elapsed %s ETA %s mean %.2f ms"
                  % (n, len(probes), hms(el),
                     hms(el/n*(len(probes)-n)), 1000.0*el/n))
            sys.stdout.flush()
    pr.wait()

el = time.time()-t_start
acc = sum(1 for v in verdicts.values() if v == "ACCEPT")
print("== %s: %d probes, %d ACCEPT, %d REFUSE, %d missing, %.1f s, %.1f ms/probe"
      % (LANG, len(probes), acc, len(verdicts)-acc,
         len(probes)-len(verdicts), el,
         1000.0*el/len(probes) if probes else 0))
out.write("__SUMMARY__|%d|%d|%d|%.3f\n"
          % (len(probes), acc, len(verdicts)-acc, el))
out.close()
PY_EOF
echo "=== acceptance lane dart done ==="
date -u +%Y-%m-%dT%H:%M:%SZ

rm -rf "$ROOT"
echo "swept $ROOT; /work free: $(df -Pm /work | awk 'NR==2{print $4}') MB"
